/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trg_tb_people_ai` AFTER INSERT ON `tb_people` FOR EACH ROW INSERT INTO `tb_logs` (
