CREATE DEFINER=`root`@`%` FUNCTION `fn_aleatorio_entero`(p_min INT, p_max INT) RETURNS int
    READS SQL DATA
BEGIN
    IF p_min IS NULL OR p_max IS NULL OR p_max < p_min THEN
        RETURN NULL;
    END IF;
    RETURN p_min + FLOOR(RAND() * (p_max - p_min + 1));
END ;;
