DELIMITER ;;
CREATE DEFINER=`root`@`%` FUNCTION `fn_estado_probabilidad`(p_prob_activo DECIMAL(5,2)) RETURNS bit(1)
    READS SQL DATA
BEGIN
    IF p_prob_activo IS NULL OR p_prob_activo >= 100 THEN
        RETURN b'1';
    END IF;
    IF p_prob_activo <= 0 THEN
        RETURN b'0';
    END IF;
    IF (RAND() * 100) < p_prob_activo THEN
        RETURN b'1';
    END IF;
    RETURN b'0';
END ;;
DELIMITER ;
